// Find All Duplicates: values 1..n, sign marking, O(1) extra memory
var dups = new List<int>();
foreach (int x in a) {
    int v = Math.Abs(x);                 // the slot may have been marked earlier
    if (a[v - 1] < 0) dups.Add(v);       // already marked — a duplicate
    else a[v - 1] = -a[v - 1];
}

